import React, { useState } from 'react';
import { NavLink } from 'react-router-dom';
import {
  Cpu,
  LayoutDashboard,
  Factory,
  Server,
  PlusCircle,
  Wrench,
  ShieldAlert,
  ChevronLeft,
  ChevronRight,
  Activity,
} from 'lucide-react';

const Sidebar = () => {
  const [collapsed, setCollapsed] = useState(false);

  const toggleSidebar = () => {
    setCollapsed(!collapsed);
  };

  return (
    <aside className={`sidebar ${collapsed ? 'collapsed' : ''}`}>
      {/* Sidebar Header Brand Logo */}
      <div className="sidebar-brand">
        <div className="brand-icon-box">
          <Cpu size={22} />
        </div>
        {!collapsed && (
          <div className="brand-text-group">
            <span className="brand-title">TexTwin</span>
            <span className="brand-badge">Digital Twin</span>
          </div>
        )}
      </div>

      {/* Navigation Links */}
      <nav className="sidebar-nav">
        <NavLink
          to="/"
          className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}
          end
          title="Dashboard"
        >
          <LayoutDashboard size={20} />
          {!collapsed && <span>Dashboard</span>}
        </NavLink>

        <NavLink
          to="/plants"
          className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}
          title="Plants & Lines"
        >
          <Factory size={20} />
          {!collapsed && <span>Plants & Lines</span>}
        </NavLink>

        <NavLink
          to="/assets"
          className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}
          title="Asset Inventory"
        >
          <Server size={20} />
          {!collapsed && <span>Asset Inventory</span>}
        </NavLink>

        <NavLink
          to="/assets/new"
          className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}
          title="Add Machine Asset"
        >
          <PlusCircle size={20} />
          {!collapsed && <span>Add Machine Asset</span>}
        </NavLink>
      </nav>

      {/* Operational Status Box */}
      {!collapsed && (
        <div className="sidebar-status-box">
          <div className="status-box-header">
            <Activity size={16} style={{ color: 'var(--status-running)' }} />
            <span>Digital Twin Sync</span>
          </div>
          <p className="status-box-sub">Connected to 6 Weaving Looms</p>
        </div>
      )}

      {/* Collapse Toggle Button */}
      <button className="sidebar-toggle-btn" onClick={toggleSidebar} title={collapsed ? 'Expand Sidebar' : 'Collapse Sidebar'}>
        {collapsed ? <ChevronRight size={18} /> : <ChevronLeft size={18} />}
      </button>
    </aside>
  );
};

export default Sidebar;
